import test from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import {
  readStoredHousingBrief,
  HousingStoredDataError,
} from "./housing-history.js";
import { DomainError } from "./errors.js";

// Literal historical JSON, not generated by the current contract/helper.
const fixtures: unknown[] = JSON.parse(
  await readFile(
    new URL("./fixtures/housing-v1.json", import.meta.url),
    "utf8",
  ),
);

test("frozen v1 fixtures retain exact JSON, unknowns, provenance and suggestions", () => {
  assert.equal(fixtures.length, 3);
  for (const fixture of fixtures) {
    const before = structuredClone(fixture);
    assert.deepEqual(readStoredHousingBrief(fixture), before);
    assert.deepEqual(fixture, before, "The decoder must not modify its input");
  }
  // Pin parsed/re-serialized JSON (formatting can change). Never update this hash to make a
  // new current schema pass: add a new version/fixture and retain these cases.
  assert.equal(
    createHash("sha256").update(JSON.stringify(fixtures)).digest("hex"),
    "c8228f147f7616b99cb71fac0e34c0bb73ef5dd7df5a0cd253d9aa41eb828744",
  );
});

test("missing, malformed and unsupported stored versions fail as safe server data errors", () => {
  for (const [content, reason] of [
    [null, "invalid_content"],
    [[], "invalid_content"],
    ["sensitive payload", "invalid_content"],
    [{}, "invalid_content"],
    [{ schemaVersion: "1" }, "invalid_content"],
    [{ schemaVersion: 0 }, "invalid_content"],
    [{ schemaVersion: 1.5 }, "invalid_content"],
    [{ schemaVersion: 1, secret: "sensitive payload" }, "invalid_content"],
    [{ schemaVersion: 2, secret: "sensitive payload" }, "unsupported_version"],
  ] as const) {
    assert.throws(
      () => readStoredHousingBrief(content),
      (error: unknown) => {
        assert.ok(error instanceof HousingStoredDataError);
        assert.equal(error.reason, reason);
        assert.ok(!(error instanceof DomainError));
        assert.ok(!error.message.includes("sensitive payload"));
        assert.equal(error.cause, undefined);
        return true;
      },
    );
  }
});

test("v1 reader does not silently normalize or accept invalid nested historical content", () => {
  const original = readStoredHousingBrief(fixtures[2]);
  for (const mutate of [
    (v: typeof original) => {
      v.starterPlan!.summary = "  Не нормализовать  ";
    },
    (v: typeof original) => {
      v.starterPlan!.summary = "Не нормализовать е\u0308";
    },
    (v: typeof original) => {
      v.answers.moveTiming.revision = 0;
    },
    (v: typeof original) => {
      v.suggestions[0]!.revision = 3;
    },
    (v: typeof original) => {
      v.suggestions[1]!.status = "rejected";
    },
    (v: typeof original) => {
      v.destination.cityCode = "OTHER" as "RU-MOW";
    },
    (v: typeof original) => {
      if (v.answers.moveTiming.status !== "unasked")
        v.answers.moveTiming.provenance.eventId =
          "AAAAAAAA-AAAA-4AAA-8AAA-AAAAAAAAAAAA";
    },
  ]) {
    const changed = structuredClone(original);
    mutate(changed);
    const before = structuredClone(changed);
    assert.throws(
      () => readStoredHousingBrief(changed),
      HousingStoredDataError,
    );
    assert.deepEqual(changed, before);
  }
});
